import fs from 'node:fs';
import crypto from 'node:crypto';
const h=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const baseline=JSON.parse(fs.readFileSync('docs/stabilization/worktree-baseline.json'));
const inv=JSON.parse(fs.readFileSync('docs/stabilization/test-inventory.json'));
const allowed=new Set(['PHASE_1_MASTER_PROGRESS_TRACKER.md','docs/TESTING.md','docs/REPORTING_ANALYTICS_REQUIREMENTS_MATRIX_2026-11-18.md','dist/index.html']);
const changed=baseline.entries.filter(e=>h(e.path)!==e.sha256).map(e=>e.path);
const unexpected=changed.filter(p=>!allowed.has(p));
const changedTests=inv.inventory.filter(e=>h(e.path)!==e.sha256).map(e=>e.path);
const scan=JSON.parse(fs.readFileSync('docs/stabilization/execution-2026-11-18/production-scan.json'));
const mismatchedAssets=scan.javascriptAssets.filter(e=>h(e.path)!==e.sha256).map(e=>e.path);
const htmlMatches=h(scan.indexHtml.path)===scan.indexHtml.sha256&&h(scan.sourceHtml.path)===scan.sourceHtml.sha256;
const requirements=[...fs.readFileSync('PHASE_1_MASTER_PROGRESS_TRACKER.md','utf8').matchAll(/^### (\d+)\./gm)].map(m=>Number(m[1]));
const requirementRowsIntact=JSON.stringify(requirements)===JSON.stringify(Array.from({length:21},(_,i)=>i+1));
const result={baselineFiles:baseline.entries.length,unchangedBaselineFiles:baseline.entries.length-changed.length,allowedDocumentationOrBuildChanges:changed,unexpectedChanges:unexpected,changedTestFiles:changedTests,verifiedTestFiles:inv.inventory.length,productionAssetHashesMatch:mismatchedAssets.length===0,productionHtmlHashesMatch:htmlMatches,requirementRowsIntact,preparedBaselineSha256:h('docs/stabilization/worktree-baseline.json'),testInventorySha256:h('docs/stabilization/test-inventory.json'),historicalScannerEvidencePreserved:h('docs/asset-scanner/current-scan.json')===baseline.entries.find(e=>e.path==='docs/asset-scanner/current-scan.json').sha256};
fs.writeFileSync('docs/stabilization/execution-2026-11-18/preservation-check.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result));
if(unexpected.length||changedTests.length||mismatchedAssets.length||!htmlMatches||!requirementRowsIntact||!result.historicalScannerEvidencePreserved)process.exitCode=1;
'@ | node --input-type=module -
